package com.ias.ticket;
import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;

/** Ordinary local cancellation only; no external owner cleanup is asserted. */
@RestController
public class Cancellations {
 final Tickets t;final StaffAccess access;
 public Cancellations(Tickets t,StaffAccess access){this.t=t;this.access=access;}
 static Problem conflict(String code){return new Problem(409,code);}
 Tickets.Actor actor(HttpServletRequest r,boolean review){Chain.source(r);long deadline=Chain.deadline(r);var v=Chain.identity("ticket-identity",Chain.cookie(r),review?"TICKET_WORK":"TICKET_CUSTOMER_CANCEL",r.getHeader("X-CSRF-TOKEN"),Chain.trace(r),deadline);Chain.fresh(v,deadline);return new Tickets.Actor(Tickets.id(v.get("tenantId")),Tickets.id(v.get("userId")),v.get("identityType").toString(),Chain.cookie(r),r.getHeader("X-CSRF-TOKEN"),Chain.trace(r),deadline,v.get("attempt").toString());}
 Map<String,Object> fields(String action,Map<String,Object>b){var required=new HashSet<>(Set.of("expectedVersion","roundId"));if(!action.equals("cancel-direct"))required.add("reason");if(action.equals("cancel-decision"))required.add("decision");var allowed=new HashSet<>(required);allowed.add("reason");if(!allowed.containsAll(b.keySet())||!b.keySet().containsAll(required)||!(b.get("expectedVersion") instanceof String))throw Tickets.bad();var data=new TreeMap<String,Object>(b);data.put("expectedVersion",Long.toString(Tickets.id(b.get("expectedVersion"))));Tickets.uuid(b.get("roundId"));if(b.containsKey("reason"))Tickets.text(b.get("reason"),action.equals("cancel-direct")?1:5,500,true);if(action.equals("cancel-decision")&&(!(b.get("decision") instanceof String)||!Set.of("APPROVE","REJECT").contains(b.get("decision"))))throw Tickets.bad();return data;}
 @PostMapping("/api/ticket/tickets/{key}/cancel") Map<String,Object> direct(@PathVariable String key,@RequestBody Map<String,Object>b,HttpServletRequest r){return perform(key,"cancel-direct",fields("cancel-direct",b),actor(r,false),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 @PostMapping("/api/ticket/tickets/{key}/cancellation-requests") Map<String,Object> request(@PathVariable String key,@RequestBody Map<String,Object>b,HttpServletRequest r){return perform(key,"cancel-request",fields("cancel-request",b),actor(r,false),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 @PostMapping("/api/ticket/tickets/{key}/cancellation-requests/{request}/decision") Map<String,Object> decide(@PathVariable String key,@PathVariable String request,@RequestBody Map<String,Object>b,HttpServletRequest r){var data=fields("cancel-decision",b);data.put("cancelRequestId",Tickets.uuid(request));return perform(key,"cancel-decision",data,actor(r,true),Tickets.uuid(Chain.single(r,"Idempotency-Key")));}
 boolean unaccepted(Map<String,Object>row){String state=row.get("status").toString();boolean candidate=state.equals("PENDING_ACCEPTANCE")||state.equals("WAITING_INFORMATION")&&"PENDING_ACCEPTANCE".equals(new Supplements(t,access).current(row,false).get("resume_state"));return candidate&&t.db.queryForObject("SELECT COUNT(*) FROM ticket_processing_record WHERE ticket_id=? AND round_id=? AND type='ACCEPT'",Long.class,row.get("id"),row.get("round_id"))==0;}
 boolean active(Map<String,Object>row){return Set.of("WAITING_ASSIGNMENT","ASSIGNED","IN_PROGRESS","PENDING_CUSTOMER_CONFIRMATION").contains(row.get("status"))||"WAITING_INFORMATION".equals(row.get("status"))&&"IN_PROGRESS".equals(new Supplements(t,access).current(row,false).get("resume_state"));}
 Map<String,Object> current(Map<String,Object>row,boolean lock){if(row.get("current_cancel_request_id")==null)return null;var rows=t.db.queryForList("SELECT * FROM ticket_cancel_request WHERE id=? AND ticket_id=? AND round_id=?"+(lock?" FOR UPDATE":""),row.get("current_cancel_request_id"),row.get("id"),row.get("round_id"));if(rows.isEmpty())throw conflict("CANCELLATION_NOT_CURRENT");return rows.getFirst();}
 Map<String,Object> fact(Map<String,Object>row){var rows=t.db.queryForList("SELECT * FROM ticket_cancellation WHERE ticket_id=? AND round_id=?",row.get("id"),row.get("round_id"));return rows.isEmpty()?null:rows.getFirst();}
 Map<String,Object> perform(String key,String action,Map<String,Object>b,Tickets.Actor a,String operation){Tickets.uuid(key);t.accessible(key,a);String digest=Tickets.hash(b);return t.tx.execute(tx->{
  t.lockActor(a.tenant(),a.user());var row=t.db.queryForMap("SELECT * FROM ticket_record WHERE id=? AND tenant_id=? FOR UPDATE",key,a.tenant());Chain.fresh(Chain.identity("ticket-identity",a.token(),action.equals("cancel-decision")?"TICKET_WORK":"TICKET_CUSTOMER_CANCEL",a.csrf(),a.trace(),a.deadline()),a.deadline());t.accessible(key,a);Map<String,Object> facts=null;
  if(action.equals("cancel-decision")){facts=access.facts(a);access.customerService(facts,row,"ticket.cancel.review");}else if(!a.type().equals("CUSTOMER")||Tickets.id(row.get("reporter_user_id"))!=a.user())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");
  var old=t.db.queryForList("SELECT * FROM ticket_action_operation WHERE operation_id=? FOR UPDATE",operation);if(!old.isEmpty()){var o=old.getFirst();if(Tickets.id(o.get("tenant_id"))!=a.tenant()||Tickets.id(o.get("actor_user_id"))!=a.user()||!o.get("ticket_id").equals(key))throw new Problem(404,"OPERATION_NOT_FOUND");if(!action.equals(o.get("action"))||!digest.equals(o.get("request_digest")))throw conflict("IDEMPOTENCY_CONFLICT");return Tickets.json(o.get("result_json"));}
  StockExecutionBoundary.guard(t,key);if(!row.get("round_id").equals(b.get("roundId")))throw conflict("ROUND_CONFLICT");long version=Tickets.id(row.get("row_version"));if(version==Long.MAX_VALUE||version!=Tickets.id(b.get("expectedVersion")))throw conflict("VERSION_CONFLICT");if(row.get("assignment_id")!=null)t.db.queryForList("SELECT id FROM ticket_assignment WHERE id=? FOR UPDATE",row.get("assignment_id"));var request=current(row,true);Instant now=new Completion(t,access).now();String state=row.get("status").toString(),record=UUID.randomUUID().toString(),next=state,body;var out=new LinkedHashMap<String,Object>();String reqId=null;
  if(action.equals("cancel-request")){if(!active(row))throw conflict("INVALID_STATE");if(request!=null)throw conflict("CANCELLATION_PENDING");new Transfers(t,access).terminate(row,a,operation,"CANCELLATION_REQUESTED",now);reqId=UUID.randomUUID().toString();t.db.update("INSERT INTO ticket_cancel_request(id,ticket_id,round_id,assignment_id,operation_id,requested_by,requested_at,reason,submitted_status) VALUES(?,?,?,?,?,?,?,?,?)",reqId,key,b.get("roundId"),row.get("assignment_id"),operation,a.user(),Timestamp.from(now),b.get("reason"),state);t.db.update("UPDATE ticket_record SET current_cancel_request_id=? WHERE id=?",reqId,key);body="原报修人申请取消："+b.get("reason");out.put("cancellationState","PENDING_REVIEW");out.put("requestedAt",now.toString());out.put("nextAction","WAIT_CANCELLATION_REVIEW");
  }else{
   if(action.equals("cancel-direct")){if(!unaccepted(row))throw conflict("INVALID_STATE");if(request!=null)throw conflict("CANCELLATION_PENDING");}
   else{reqId=Tickets.uuid(b.get("cancelRequestId"));if(request==null||!request.get("id").equals(reqId))throw conflict("CANCELLATION_NOT_CURRENT");if(Tickets.id(request.get("requested_by"))==a.user())throw new Problem(403,"ACCESS_DENIED");if(!active(row))throw conflict("INVALID_STATE");if(t.db.queryForObject("SELECT COUNT(*) FROM ticket_cancel_decision WHERE request_id=?",Long.class,reqId)>0)throw conflict("CANCELLATION_ALREADY_DECIDED");}
   boolean cancel=action.equals("cancel-direct")||b.get("decision").equals("APPROVE");if(cancel){new ApprovalBoundary(t,access).requireNoExternal(key);new Completion(t,access).requireSupported(row);var cancelled=terminate(row,a,operation,reqId,b.get("reason"),now);out.put("cancellation",viewFact(cancelled));out.put("cancelledAt",now.toString());next="CANCELLED";body="工单已取消。"+(b.containsKey("reason")?b.get("reason"):"");out.put("nextAction","VIEW_TICKET");}else{body="取消申请已拒绝："+b.get("reason");out.put("nextAction","CONTINUE_CURRENT_WORKFLOW");}
   if(reqId!=null){String decision=cancel?"APPROVED":"REJECTED";t.db.update("INSERT INTO ticket_cancel_decision(request_id,ticket_id,round_id,operation_id,decision,reason,decided_by,decided_at) VALUES(?,?,?,?,?,?,?,?)",reqId,key,b.get("roundId"),operation,decision,b.get("reason"),a.user(),Timestamp.from(now));out.put("decision",b.get("decision"));out.put("cancellationState",decision);out.put("decidedAt",now.toString());}t.db.update("UPDATE ticket_record SET current_cancel_request_id=NULL WHERE id=?",key);
  }
  t.db.update("INSERT INTO ticket_processing_record(id,ticket_id,round_id,assignment_id,operation_id,actor_user_id,type,body,work_hours,visibility,qualification_json,row_version,occurred_at) VALUES(?,?,?,?,?,?,?,?,0,'CUSTOMER_VISIBLE',?,?,?)",record,key,b.get("roundId"),row.get("assignment_id"),operation,a.user(),action.replace('-','_').toUpperCase(Locale.ROOT),body,Chain.JSON.writeValueAsString(facts==null?Map.of("identityType","CUSTOMER"):new Workflow(t,access).qualification(facts)),version+1,Timestamp.from(now));t.db.update("UPDATE ticket_record SET status=?,row_version=row_version+1 WHERE id=?",next,key);
  out.putAll(Map.of("operationId",operation,"action",action,"state",action.equals("cancel-request")?"PENDING_REVIEW":"COMPLETED","ticketId",key,"roundId",b.get("roundId"),"status",next,"rowVersion",Long.toString(version+1),"recordId",record));out.put("assignmentId",row.get("assignment_id"));if(reqId!=null)out.put("cancelRequestId",reqId);t.db.update("INSERT INTO ticket_action_operation(operation_id,tenant_id,actor_user_id,ticket_id,action,request_digest,result_json,created_at) VALUES(?,?,?,?,?,?,?,?)",operation,a.tenant(),a.user(),key,action,digest,Chain.JSON.writeValueAsString(out),Timestamp.from(now));t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,?,?)",operation,a.tenant(),a.user(),"WORKFLOW_"+action.replace('-','_').toUpperCase(Locale.ROOT),Timestamp.from(now));Chain.remaining(a.deadline());return out;
 });}
 Map<String,Object> terminate(Map<String,Object>row,Tickets.Actor a,String operation,String request,Object reason,Instant time){
  new Transfers(t,access).terminate(row,a,operation,"TICKET_CANCELLED",time);var supplement=new Supplements(t,access).current(row,true);var completion=new Completion(t,access);var solution=completion.current(row,true);Object solutionId=solution!=null&&completion.decision(solution.get("id"),true)==null?solution.get("id"):null;var timing=completion.timing(row,time);timing.put("clockStopped",true);timing.put("terminalReason","CANCELLED");timing.put("terminatedAt",time.toString());timing.put("terminatedEffectiveResolutionMs",timing.get("effectiveResolutionMs"));timing.put("needsCoordination",false);timing.put("currentWaitOver72Hours",false);timing.put("currentSupplementWaitOver72Hours",false);timing.put("finalFrozen",false);timing.put("finalResolutionOverdue",null);
  var check=Map.of("scope","ORDINARY_REPAIR_ONLY","relatedWorkflows","NOT_ENABLED");t.db.update("INSERT INTO ticket_cancellation(ticket_id,round_id,operation_id,request_id,source,cancelled_by,cancelled_at,reason,previous_status,assignment_id,terminated_supplement_id,terminated_solution_id,check_json,timing_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",row.get("id"),row.get("round_id"),operation,request,request==null?"DIRECT":"APPROVED",a.user(),Timestamp.from(time),reason,row.get("status"),row.get("assignment_id"),supplement==null?null:supplement.get("id"),solutionId,Chain.JSON.writeValueAsString(check),Chain.JSON.writeValueAsString(timing));
  for(var file:t.db.queryForList("SELECT f.id FROM ticket_file f WHERE f.supplement_ticket_id=? AND f.supplement_round_id=? AND f.state='UPLOADING' AND NOT EXISTS(SELECT 1 FROM ticket_file_reference x WHERE x.file_id=f.id) ORDER BY f.id FOR UPDATE",row.get("id"),row.get("round_id")))t.db.update("UPDATE ticket_file SET state='FAILED',generation=NULL,lease_until=NULL,updated_at=? WHERE id=?",Timestamp.from(time),file.get("id"));t.db.update("UPDATE ticket_record SET current_supplement_id=NULL WHERE id=?",row.get("id"));return t.db.queryForMap("SELECT * FROM ticket_cancellation WHERE ticket_id=? AND round_id=?",row.get("id"),row.get("round_id"));
 }
 void confirmed(Map<String,Object>row,Tickets.Actor a,String operation,Instant time){var req=current(row,true);if(req==null)return;t.db.update("INSERT INTO ticket_cancel_decision(request_id,ticket_id,round_id,operation_id,decision,reason,decided_by,decided_at) VALUES(?,?,?,?,'NO_LONGER_APPLICABLE','CUSTOMER_CONFIRMED',?,?)",req.get("id"),row.get("id"),row.get("round_id"),operation,a.user(),Timestamp.from(time));t.db.update("UPDATE ticket_record SET current_cancel_request_id=NULL WHERE id=?",row.get("id"));t.db.update("INSERT INTO ticket_audit(operation_id,tenant_id,actor_user_id,action,occurred_at) VALUES(?,?,?,'CANCELLATION_NO_LONGER_APPLICABLE',?)",operation,a.tenant(),a.user(),Timestamp.from(time));}
 Map<String,Object> viewFact(Map<String,Object>f){var out=new LinkedHashMap<String,Object>();for(String[] p:new String[][]{{"source","source"},{"cancelRequestId","request_id"},{"reason","reason"},{"previousStatus","previous_status"},{"roundId","round_id"},{"assignmentId","assignment_id"}})out.put(p[0],f.get(p[1]));out.put("cancelledBy",f.get("cancelled_by").toString());out.put("cancelledAt",Tickets.utc(f.get("cancelled_at")));out.put("check",Tickets.json(f.get("check_json")));return out;}
 Map<String,Object> view(Map<String,Object>r){var out=new LinkedHashMap<String,Object>();for(String[]p:new String[][]{{"cancelRequestId","id"},{"ticketId","ticket_id"},{"roundId","round_id"},{"assignmentId","assignment_id"},{"reason","reason"},{"submittedStatus","submitted_status"}})out.put(p[0],r.get(p[1]));out.put("requestedBy",r.get("requested_by").toString());out.put("requestedAt",Tickets.utc(r.get("requested_at")));var d=t.db.queryForList("SELECT * FROM ticket_cancel_decision WHERE request_id=?",r.get("id"));out.put("state",d.isEmpty()?"PENDING_REVIEW":d.getFirst().get("decision"));out.put("decision",d.isEmpty()?null:Map.of("decision",d.getFirst().get("decision"),"reason",d.getFirst().get("reason"),"decidedBy",d.getFirst().get("decided_by").toString(),"decidedAt",Tickets.utc(d.getFirst().get("decided_at"))));return out;}
 @GetMapping("/api/ticket/tickets/{key}/cancellation-requests") Map<String,Object> history(@PathVariable String key,HttpServletRequest r){var a=t.actor(r,false);var visible=t.accessible(key,a);String selectedRound=new Rounds(t).selected(r,visible);for(var p:r.getParameterMap().entrySet())if(!Set.of("page","size","roundId").contains(p.getKey())||p.getValue().length!=1)throw Tickets.bad();long page=r.getParameter("page")==null?1:Tickets.id(r.getParameter("page")),size=r.getParameter("size")==null?20:Tickets.id(r.getParameter("size"));if(page>1000000||!Set.of(20L,50L,100L).contains(size))throw Tickets.bad();return Map.of("items",t.db.queryForList("SELECT * FROM ticket_cancel_request WHERE ticket_id=? AND round_id=? ORDER BY requested_at DESC,id DESC LIMIT ? OFFSET ?",key,selectedRound,size,(page-1)*size).stream().map(this::view).toList(),"total",t.db.queryForObject("SELECT COUNT(*) FROM ticket_cancel_request WHERE ticket_id=? AND round_id=?",Long.class,key,selectedRound),"page",page,"size",size);}
 void project(Map<String,Object>out,Map<String,Object>row,Tickets.Actor a){var req=current(row,false);var cancelled=fact(row);out.put("currentCancellation",req==null?null:view(req));out.put("cancellation",cancelled==null?null:viewFact(cancelled));var actions=new ArrayList<String>((List<String>)out.get("allowedActions"));if(cancelled!=null)actions.clear();else if(a.type().equals("CUSTOMER")){if(unaccepted(row))actions.add("cancel-direct");else if(active(row)&&req==null)actions.add("cancel-request");}else{var f=access.facts(a);if(req!=null&&active(row)&&access.company(f,row.get("company_id"))&&access.permission(f,"ticket.cancel.review"))actions.addAll(List.of("cancel-approve","cancel-reject"));}out.put("allowedActions",actions);}
}
